effect.shader:
float bayer(vec2 p){
  vec2 f = floor(mod(p, 4.0));
  float m = 0.0;
  if (f.y < 0.5){ m = f.x < 0.5 ? 0.0 : 2.0; }
  else { m = f.x < 0.5 ? 3.0 : 1.0; }
  return (m + 0.5) / 4.0;
}
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float th = bayer(uv * acScreenSize / max(scale, 1.0)) - 0.5;
  float n = max(levels, 2.0) - 1.0;
  vec3 q;
  if (color) q = floor(c * n + 0.5 + th) / n;
  else { float l = floor(gmLum(c) * n + 0.5 + th) / n; q = vec3(l); }
  vec3 col = mix(c, clamp(q, 0.0, 1.0), mixAmt);
  gl_FragColor = vec4(col * a, a);
}
